   963	    PropertyHandler handler = FindSetPropertyHandler(aKey);
   964	
   965	    if (handler != NULL)
   966	    {
   967	        mDisableStreamWrite = false;
   968	        error               = (this->*handler)();
   969	        mDisableStreamWrite = true;
   970	    }
   971	    else
   972	    {
   973	        // If there is no "set" handler, check if this property is one of the
   974	        // ones that require different treatment.
