   987	            // An `OT_ERROR_NOT_FOUND` status from vendor handler indicates
   988	            // that it does not support the given property key. In that
   989	            // case, `didHandle` is set to `false` so a `LAST_STATUS` with
   990	            // `PROP_NOT_FOUND` is emitted. Otherwise, we fall through to
   991	            // prepare the response.
   992	
   993	            didHandle = (error != OT_ERROR_NOT_FOUND);
   994	        }
   995	#endif
   996	
   997	        VerifyOrExit(didHandle, error = PrepareLastStatusResponse(aHeader, SPINEL_STATUS_PROP_NOT_FOUND));
   998	    }
   999	
