  1001	    {
  1002	        error = PrepareSetResponse(aHeader, aKey);
  1003	    }
  1004	    else
  1005	    {
  1006	        error = PrepareLastStatusResponse(aHeader, ThreadErrorToSpinelStatus(error));
  1007	    }
